```python
import asyncio
from fastmcp import FastMCP, Client

mcp = FastMCP("ConfigServer")


@mcp.resource("data://config")
def get_config() -> dict:
    return {"debug": True, "version": "1.0.0"}


async def main() -> None:
    client = Client(mcp)  # in-memory transport: pass the FastMCP server object directly
    async with client:
        contents = await client.read_resource("data://config")
        for content in contents:
            if hasattr(content, "text"):
                print(content.text)
            else:
                print(content)


if __name__ == "__main__":
    asyncio.run(main())
